.site-ui.home-page :is(.hero-content,.section){padding-inline:max(var(--ui-gutter),calc((100% - var(--ui-width))/2))}
/* The shared gutters use the full hero width. A narrower max-width here would
   subtract viewport-sized padding from a capped box on wide desktop screens. */
.site-ui.home-page .hero-content{max-width:none}
